var t=`0971-kimchi-jjigae`;var n=`world-0971`;var s=`KR`;var a=`east-asia`;var r=4;var g=37;var o={en:`Kimchi Jjigae`,ua:`Кімчі ччіге`};var h={en:`Kimchi Jjigae is a South Korea dish made with pork belly, kimchi, garlic, tofu (firm). This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Кімчі ччіге, страва кухні країни Південна Корея. Основні складники: свиняча грудинка, кімчі, часник, твердий тофу. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var m=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`pork-belly`,380,`g`],[`kimchi`,520,`g`],[`garlic`,4,`clove`],[`sesame-oil`,35,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 22 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 22 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:22,i:[[`dashi-stock`,900,`ml`],[`tofu-firm`,360,`g`],[`gochugaru`,8,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,75,`g`]]}];var d={slug:t,id:n,country:`KR`,region:a,servings:4,minutes:37,title:o,text:h,steps:m};export{s as country,d as default,n as id,g as minutes,a as region,r as servings,t as slug,m as steps,h as text,o as title};